const sidebar=$('#sidebar'),menu=$('#menu-toggle');let priorFocus=null;function closeDrawer(){if(!document.body.classList.contains('nav-open'))return;document.body.classList.remove('nav-open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');if(priorFocus?.focus)priorFocus.focus()};menu.addEventListener('click',()=>{if(document.body.classList.contains('nav-open')){closeDrawer();return}priorFocus=document.activeElement;document.body.classList.add('nav-open');menu.setAttribute('aria-expanded','true');menu.setAttribute('aria-label','Close navigation');const first=sidebar.querySelector('button');first?.focus()});document.addEventListener('keydown',e=>{if(!document.body.classList.contains('nav-open'))return;if(e.key==='Escape'){e.preventDefault();closeDrawer()}if(e.key==='Tab'){const f=[...sidebar.querySelectorAll('button,a,input,select,textarea,[tabindex]:not([tabindex="-1"])')].filter(el=>!el.disabled);if(!f.length)return;const first=f[0],last=f[f.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});

