$('#export-progress').onclick=()=>{const blob=new Blob([JSON.stringify({format:'mh-trainer-progress',version:1,exportedAt:new Date().toISOString(),progress:S,community:(()=>{try{return JSON.parse(localStorage.getItem('mhComm')||'{}')}catch(_){return {}}})(),theme:(()=>{try{return localStorage.getItem('mhTrainerTheme')}catch(_){return null}})()},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='mh-trainer-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('#import-progress').onclick=()=>$('#progress-file').click();$('#progress-file').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{const obj=JSON.parse(await file.text());const imported=obj?.progress;if(obj?.format!=='mh-trainer-progress'||!imported||typeof imported!=='object')throw new Error('This is not an MH Trainer progress backup.');if(!confirm('Import this backup? It will replace the progress currently saved in this browser.'))return;S=Object.assign({quiz:{},known:[],cases:{},osce:{},sdomhLearning:{},sdomhMatching:{},sdomhCasePlans:{},mhaPathways:{}},imported);if(!S.mhaPathways)S.mhaPathways={};if(!S.sdomhLearning)S.sdomhLearning={};if(!S.sdomhMatching)S.sdomhMatching={};if(!S.sdomhCasePlans)S.sdomhCasePlans={};save();if(obj.community)localStorage.setItem('mhComm',JSON.stringify(obj.community));if(obj.theme)setTheme(obj.theme);go(Object.keys(names).includes(location.hash.slice(1))?location.hash.slice(1):'home',{fromHistory:true});alert('Progress imported.')}catch(err){alert('Could not import progress: '+err.message)}finally{e.target.value=''}};
